import java.util.ArrayList;
import java.util.List;

// 1. Core Payable Interface
public interface Payable {
    double calculateEarnings();
    String getPaymentDescription();
}

// 2. Abstract Employee Superclass
abstract class Employee implements Payable {
    protected String id;
    protected String name;
    protected String departmentName;
    private String ssn;

    public Employee(String id, String name, String departmentName, String ssn) {
        if (id == null || id.trim().isEmpty()) throw new IllegalArgumentException("ID required.");
        if (name == null || name.trim().isEmpty()) throw new IllegalArgumentException("Name required.");
        this.id = id.trim();
        this.name = name.trim();
        this.departmentName = (departmentName != null) ? departmentName.trim() : "General";
        this.ssn = (ssn != null) ? ssn.trim() : "000-00-0000";
    }

    public String getMaskedSsn() {
        if (ssn.length() >= 4) {
            return "XXX-XX-" + ssn.substring(ssn.length() - 4);
        }
        return "XXX-XX-0000";
    }

    public String getId() { return id; }
    public String getName() { return name; }
    public String getDepartmentName() { return departmentName; }
}

// 3. Salaried Employee
class SalariedEmployee extends Employee {
    private double weeklySalary;

    public SalariedEmployee(String id, String name, String dept, String ssn, double weeklySalary) {
        super(id, name, dept, ssn);
        this.weeklySalary = Math.max(0, weeklySalary);
    }

    @Override
    public double calculateEarnings() {
        return weeklySalary * 4.0; // Monthly equivalent
    }

    @Override
    public String getPaymentDescription() {
        return String.format("Salaried (Weekly Base: $%.2f)", weeklySalary);
    }
}

// 4. Hourly Employee with Overtime
class HourlyEmployee extends Employee {
    private double hourlyRate;
    private double hoursWorked;

    public HourlyEmployee(String id, String name, String dept, String ssn, double hourlyRate, double hoursWorked) {
        super(id, name, dept, ssn);
        this.hourlyRate = Math.max(0, hourlyRate);
        this.hoursWorked = Math.max(0, hoursWorked);
    }

    @Override
    public double calculateEarnings() {
        if (hoursWorked <= 40.0) {
            return hoursWorked * hourlyRate;
        } else {
            double regularPay = 40.0 * hourlyRate;
            double overtimePay = (hoursWorked - 40.0) * (hourlyRate * 1.5);
            return regularPay + overtimePay;
        }
    }

    @Override
    public String getPaymentDescription() {
        return String.format("Hourly (%.1f hrs @ $%.2f/hr + 1.5x OT)", hoursWorked, hourlyRate);
    }
}

// 5. Commission Employee
class CommissionEmployee extends Employee {
    private double grossSales;
    private double commissionRate;

    public CommissionEmployee(String id, String name, String dept, String ssn, double grossSales, double commissionRate) {
        super(id, name, dept, ssn);
        this.grossSales = Math.max(0, grossSales);
        this.commissionRate = (commissionRate > 0 && commissionRate <= 0.50) ? commissionRate : 0.10;
    }

    @Override
    public double calculateEarnings() {
        return grossSales * commissionRate;
    }

    @Override
    public String getPaymentDescription() {
        return String.format("Commission ($%.2f sales @ %.1f%%)", grossSales, commissionRate * 100);
    }
}

// 6. Department Aggregate
class Department {
    private String name;
    private double monthlyBudget;
    private List<Employee> employees;

    public Department(String name, double monthlyBudget) {
        this.name = name;
        this.monthlyBudget = monthlyBudget;
        this.employees = new ArrayList<>();
    }

    public void hireEmployee(Employee emp) {
        if (emp != null) employees.add(emp);
    }

    public double calculateTotalPayroll() {
        double total = 0.0;
        for (Employee e : employees) total += e.calculateEarnings();
        return total;
    }

    public boolean isOverBudget() {
        return calculateTotalPayroll() > monthlyBudget;
    }

    public String getName() { return name; }
    public double getMonthlyBudget() { return monthlyBudget; }
    public List<Employee> getEmployees() { return employees; }
}

// 7. PaySlip Generator
class PaySlip {
    public static void printVoucher(Employee emp) {
        double gross = emp.calculateEarnings();
        double tax = gross * 0.20; // 20% flat tax
        double net = gross - tax;

        System.out.println("=======================================================================");
        System.out.println("                       OFFICIAL PAYSLIP VOUCHER                        ");
        System.out.println("                         NEXUS ENTERPRISES CORP                        ");
        System.out.println("=======================================================================");
        System.out.printf("Employee ID:       %s%n", emp.getId());
        System.out.printf("Employee Name:     %s%n", emp.getName());
        System.out.printf("Department:        %s%n", emp.getDepartmentName());
        System.out.printf("SSN Reference:     %s%n", emp.getMaskedSsn());
        System.out.printf("Payment Terms:     %s%n", emp.getPaymentDescription());
        System.out.println("-----------------------------------------------------------------------");
        System.out.printf("Gross Earnings:    $%.2f%n", gross);
        System.out.printf("Tax Deductions:    $%.2f (20.0%% statutory withholdings)%n", tax);
        System.out.println("-----------------------------------------------------------------------");
        System.out.printf("NET PAY DISBURSED: $%.2f%n", net);
        System.out.println("Payment Status:    AUTHORIZED / FUNDS CLEARED");
        System.out.println("=======================================================================\n");
    }
}

